Here is the commit message:
thunderbolt: Bound root directory content to block size

__tb_property_parse_dir() does not check that content_offset +
content_len fits within block_len for the root directory case.
When rootdir->length equals or exceeds block_len - 2, the entry
loop reads past the allocated property block.

Add a bounds check after computing content_offset and content_len
to reject directories whose content extends past the block.

Fixes: cdae7c07e3e3 ("thunderbolt: Add support for XDomain properties")
Cc: stable@vger.kernel.org
Assisted-by: Claude:claude-opus-4-7
Signed-off-by: Michael Bommarito <michael.bommarito@gmail.com>
Signed-off-by: Mika Westerberg <mika.westerberg@linux.intel.com>

Here is the root cause:
The function `__tb_property_parse_dir()` lacks a bounds check for the root directory case; when `rootdir->length` equals or exceeds `block_len - 2`, `content_offset` and `content_len` are computed without verifying that `content_offset + content_len <= block_len`, allowing the loop to read past the allocated property block and causing an out-of-bounds access.

Here is the patch:

 static struct tb_property_dir *__tb_property_parse_dir(const u32 *block,
 	size_t block_len, unsigned int dir_offset, size_t dir_len, bool is_root,
 	unsigned int depth)
 {
 	const struct tb_property_entry *entries;
 	size_t i, content_len, nentries;
 	unsigned int content_offset;
 	struct tb_property_dir *dir;

 	if (depth > TB_PROPERTY_MAX_DEPTH)
 		return NULL;

 	dir = kzalloc_obj(*dir);
 	if (!dir)
 		return NULL;

 	INIT_LIST_HEAD(&dir->properties);

 	if (is_root) {
 		content_offset = dir_offset + 2;
 		content_len = dir_len;
+		if (content_offset + content_len > block_len) {
+			tb_property_free_dir(dir);
+			return NULL;
+		}
 	} else {
 		if (dir_len < 4) {
 			tb_property_free_dir(dir);
 			return NULL;
 		}
 		dir->uuid = kmemdup(&block[dir_offset], sizeof(*dir->uuid),
 				    GFP_KERNEL);
 		if (!dir->uuid) {
 			tb_property_free_dir(dir);
 			return NULL;
 		}
 		content_offset = dir_offset + 4;
 		content_len = dir_len - 4; /* Length includes UUID */
 	}

 	entries = (const struct tb_property_entry *)&block[content_offset];
 	nentries = content_len / (sizeof(*entries) / 4);

 	for (i = 0; i < nentries; i++) {
 		struct tb_property *property;

 		property = tb_property_parse(block, block_len, &entries[i], depth);
 		if (!property) {
 			tb_property_free_dir(dir);
 			return NULL;
 		}

 		list_add_tail(&property->list, &dir->properties);
 	}

 	return dir;
 }



